    """Keeps audit_entries rows in the database, with SQL through MySQL Connector/Python. It never commits: the transaction belongs to whoever holds the connection."""

    def __init__(self, connection: Connection) -> None:
        self._connection = connection

    def find_by_entry_no(self, entry_no: int) -> AuditEntry | None:
        """The row with this primary key, or None."""
        row = fetch_one(self._connection, 'SELECT ' + _COLUMNS + ' FROM `audit_entries` WHERE `entry_no` = %s', (to_db(entry_no),))
        return _entity(row) if row is not None else None

    def list(self, offset: int = 0, limit: int = 50) -> Page[AuditEntry]:
        """At most `limit` rows from `offset`, by primary key, and how many there are."""
        rows = fetch_all(self._connection, 'SELECT ' + _COLUMNS + ' FROM `audit_entries` ORDER BY `entry_no` LIMIT %s OFFSET %s', (limit, offset))
        counted = fetch_one(self._connection, 'SELECT COUNT(*) FROM `audit_entries`')
        total = int(counted[0]) if counted is not None else 0
        return Page(items=[_entity(row) for row in rows], total=total, offset=offset, limit=limit)

    def list_by_order_id(self, order_id: int) -> list[AuditEntry]:
        """Rows with this orderId, by primary key."""
        rows = fetch_all(self._connection, 'SELECT ' + _COLUMNS + ' FROM `audit_entries` WHERE `orderId` = %s ORDER BY `entry_no`', (to_db(order_id),))
        return [_entity(row) for row in rows]

    def insert(self, entity: AuditEntry) -> AuditEntry:
        """Stores a new row; the values the database fills are read back."""
        try:
            given = [
                ('`entry_no`', entity.entry_no),
                ('`orderId`', entity.order_id),
                ('`message`', entity.message),
            ]
            given = [(column, value) for column, value in given if value is not None]
            names = ", ".join(column for column, _ in given)
            marks = ", ".join('%s' for _ in given)
            new_id = execute(self._connection, f'INSERT INTO `audit_entries` ({names}) VALUES ({marks})', tuple(to_db(value) for _, value in given))
            if entity.entry_no is None:
                entity.entry_no = new_id
        except IntegrityError as error:
            self._connection.rollback()
            raise ConflictError("AuditEntry", "the database refused the change: " + str(error)) from error
        row = fetch_one(self._connection, 'SELECT ' + _COLUMNS + ' FROM `audit_entries` WHERE `entry_no` = %s', (to_db(entity.entry_no),))
        if row is None:
            raise LookupError("The AuditEntry just written is not there")
        return _entity(row)

    def update(self, entity: AuditEntry) -> AuditEntry:
        """Stores the changes made to a row read from this repository."""
        try:
            execute(self._connection, 'UPDATE `audit_entries` SET `orderId` = %s, `message` = %s WHERE `entry_no` = %s', (to_db(entity.order_id), to_db(entity.message), to_db(entity.entry_no),))
        except IntegrityError as error:
            self._connection.rollback()
            raise ConflictError("AuditEntry", "the database refused the change: " + str(error)) from error
        row = fetch_one(self._connection, 'SELECT ' + _COLUMNS + ' FROM `audit_entries` WHERE `entry_no` = %s', (to_db(entity.entry_no),))
        if row is None:
            raise LookupError("The AuditEntry just written is not there")
        return _entity(row)

    def delete(self, entity: AuditEntry) -> None:
        """Removes a row read from this repository."""
