            if isinstance(value, str) and len(value) > 5:
                errors.append(FieldError("code", "is longer than 5 characters"))
        if errors:
            raise ValidationFailedError("Thing", errors)

    def _check(self, values: dict[str, Any], current: Thing | None) -> None:
        """Every check before a write: the values, the rows they point to, the unique values."""
        self._validate_all(values, current)

    def _find(self, id: bytes) -> Thing:
        """The Thing with this key; NotFoundError when there is none."""
        entity = self._uow.things.find_by_id(id)
        if entity is None:
            raise NotFoundError("Thing", id)
        return entity

    def create_thing(self, thing: Thing) -> Thing:
        """Stores a new Thing after checking it."""
        values = {name: getattr(thing, name) for name in _FIELDS}
        with self._uow.transaction():
            self._check(values, None)
            created = self._uow.things.insert(thing)
            return created

    def get_thing(self, id: bytes) -> Thing:
        """The Thing with this key; NotFoundError when there is none."""
        return self._find(id)

    def list_things(self, offset: int = 0, limit: int = 50) -> Page[Thing]:
        """A page of things, by primary key."""
        return self._uow.things.list(offset, limit)

    def update_thing(self, id: bytes, changes: Mapping[str, Any]) -> Thing:
        """Changes the given values of a Thing."""
        values = dict(changes)
        with self._uow.transaction():
            current = self._find(id)
            self._check(values, current)
            for name, value in values.items():
                setattr(current, name, value)
            updated = self._uow.things.update(current)
            return updated

    def delete_thing(self, id: bytes) -> None:
        """Deletes a Thing."""
        with self._uow.transaction():
            current = self._find(id)
            self._uow.things.delete(current)

